/// Verifies that `solve(n,k,participations)` returns exactly
/// floor( (# of entries among the first `min(n,participations.len())`
/// whose attendance ≤ max(0,5−k)) / 3 ).
#[requires(true)]
#[ensures(|res: u8| {
    // spec‐level snapshot of the Rust Vec<u8>:
    let seq: Seq<u8> = participations@;
    // how many entries we actually look at
    let limit: usize = if (n as usize) < seq.len() { n as usize } else { seq.len() };
    // a participant is eligible iff att ≤ max_att
    let max_att: u8 = if k <= 5u8 { 5u8 - k } else { 0u8 };
    // filter down to the eligible ones and count them
    let elig: Seq<u8> = seq[..limit].filter(|att| *att <= max_att);
    // the implementation returns exactly floor(elig.len()/3)
    res as usize == elig.len() / 3
})]
fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many entries we actually consider
    let limit = std::cmp::min(n as usize, participations.len());
    // A participant is eligible if (5 - attendance_count) ≥ k,
    // i.e., attendance_count ≤ 5 - k (saturating at 0).
    let max_attendance = 5u8.saturating_sub(k);

    // Count eligible participants among the first `limit` entries
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&att| att <= max_attendance)
        .count();

    // Each team needs 3 participants
    (eligible_count / 3) as u8
}

